INSERT INTO public.success_reviews (id, data, status, is_example, sort_order) VALUES
  ('example-case-01', '{"id":"example-case-01","isExample":true,"title":"[예시] 월급이 압류된 직장인의 상담 흐름","category":"급여 압류","author":"가상 사례","originalDebt":0,"remainingDebt":0,"lawyerId":"","lawyerName":"예시","lawyerAvatar":"","content":"① 압류 통지 날짜와 채권자 수를 정리합니다. ② 변호사가 개인회생 신청과 함께 중지·금지명령을 신청할 수 있는지 설명합니다. ③ 압류된 금액이 회생 절차에서 어떻게 다뤄지는지 안내받습니다. ④ 급여명세서·원천징수영수증 등 준비 서류 목록을 받습니다. 실제 진행 여부와 결과는 개별 사정과 법원 판단에 따라 달라집니다.","tags":["#상담절차","#예시"]}'::jsonb, 'draft', true, 100),
  ('example-case-02', '{"id":"example-case-02","isExample":true,"title":"[예시] 자영업을 정리하고 남은 사업 채무 상담 흐름","category":"사업 실패","author":"가상 사례","originalDebt":0,"remainingDebt":0,"lawyerId":"","lawyerName":"예시","lawyerAvatar":"","content":"① 폐업 시점과 사업자 대출·카드 채무를 나눠 적습니다. ② 변호사가 지금 소득 형태(급여·재취업 준비)에 맞는 절차를 함께 검토합니다. ③ 폐업사실증명·부가세 신고 자료 등 소명 서류를 안내받습니다. ④ 회생과 파산 중 어떤 절차가 맞는지 변호사와 상담합니다. 실제 진행 여부와 결과는 개별 사정과 법원 판단에 따라 달라집니다.","tags":["#상담절차","#예시"]}'::jsonb, 'draft', true, 101),
  ('example-case-03', '{"id":"example-case-03","isExample":true,"title":"[예시] 병원비 때문에 생긴 카드 채무 상담 흐름","category":"의료비","author":"가상 사례","originalDebt":0,"remainingDebt":0,"lawyerId":"","lawyerName":"예시","lawyerAvatar":"","content":"① 치료 기간과 의료비 지출 내역을 정리합니다. ② 변호사가 채무가 늘어난 경위를 진술서에 어떻게 적는지 설명합니다. ③ 진단서·영수증 같은 소명 자료를 안내받습니다. ④ 앞으로의 치료비가 생계비에 반영될 수 있는지 상담합니다. 실제 진행 여부와 결과는 개별 사정과 법원 판단에 따라 달라집니다.","tags":["#상담절차","#예시"]}'::jsonb, 'draft', true, 102),
  ('example-case-04', '{"id":"example-case-04","isExample":true,"title":"[예시] 전세사기 피해로 보증금을 못 돌려받은 경우","category":"전세사기 피해","author":"가상 사례","originalDebt":0,"remainingDebt":0,"lawyerId":"","lawyerName":"예시","lawyerAvatar":"","content":"① 전세사기피해자 결정 여부와 보증금 대출을 정리합니다. ② 변호사가 피해자 지원 제도와 회생 절차를 함께 설명합니다. ③ 결정문·임대차계약서 등 자료를 안내받습니다. ④ 변제기간 등 법원 실무 기준을 변호사와 확인합니다. 실제 진행 여부와 결과는 개별 사정과 법원 판단에 따라 달라집니다.","tags":["#상담절차","#예시"]}'::jsonb, 'draft', true, 103),
  ('example-case-05', '{"id":"example-case-05","isExample":true,"title":"[예시] 대부업·사채 독촉이 심한 경우","category":"사채·대부","author":"가상 사례","originalDebt":0,"remainingDebt":0,"lawyerId":"","lawyerName":"예시","lawyerAvatar":"","content":"① 채권자별 연락 방식과 횟수를 기록합니다. ② 변호사가 불법 추심 대응과 법적 절차를 나눠 설명합니다. ③ 개인 채권자도 채권자목록에 적어야 한다는 점을 안내받습니다. ④ 필요하면 금지명령 신청 시기를 상담합니다. 실제 진행 여부와 결과는 개별 사정과 법원 판단에 따라 달라집니다.","tags":["#상담절차","#예시"]}'::jsonb, 'draft', true, 104),
  ('example-case-06', '{"id":"example-case-06","isExample":true,"title":"[예시] 사회초년생의 학자금·카드론 상담 흐름","category":"청년 채무","author":"가상 사례","originalDebt":0,"remainingDebt":0,"lawyerId":"","lawyerName":"예시","lawyerAvatar":"","content":"① 소득과 채무 종류(학자금·카드론·대출)를 나눠 적습니다. ② 변호사가 학자금 대출의 처리 방식이 절차마다 다르다는 점을 설명합니다. ③ 재직 기간이 짧을 때 준비할 소득 자료를 안내받습니다. ④ 신용회복위원회 채무조정과 회생의 차이를 비교합니다. 실제 진행 여부와 결과는 개별 사정과 법원 판단에 따라 달라집니다.","tags":["#상담절차","#예시"]}'::jsonb, 'draft', true, 105),
  ('example-case-07', '{"id":"example-case-07","isExample":true,"title":"[예시] 만 65세 이상 연금 소득자의 상담 흐름","category":"고령자","author":"가상 사례","originalDebt":0,"remainingDebt":0,"lawyerId":"","lawyerName":"예시","lawyerAvatar":"","content":"① 연금 종류와 매달 받는 금액을 정리합니다. ② 변호사가 연금 소득이 절차에서 어떻게 평가되는지 설명합니다. ③ 파산과 회생 중 어떤 절차를 검토할지 상담합니다. ④ 건강보험 자격·연금 수령 증빙을 안내받습니다. 실제 진행 여부와 결과는 개별 사정과 법원 판단에 따라 달라집니다.","tags":["#상담절차","#예시"]}'::jsonb, 'draft', true, 106),
  ('example-case-08', '{"id":"example-case-08","isExample":true,"title":"[예시] 이혼 뒤 남은 공동 채무 상담 흐름","category":"이혼 후 채무","author":"가상 사례","originalDebt":0,"remainingDebt":0,"lawyerId":"","lawyerName":"예시","lawyerAvatar":"","content":"① 이혼 시기와 재산분할·양육비 약정을 정리합니다. ② 변호사가 전 배우자 명의 채무와 본인 채무를 구분합니다. ③ 양육비 지급 여부가 생계비 판단에 쓰인다는 점을 안내받습니다. ④ 이혼 관련 서류 목록을 받습니다. 실제 진행 여부와 결과는 개별 사정과 법원 판단에 따라 달라집니다.","tags":["#상담절차","#예시"]}'::jsonb, 'draft', true, 107),
  ('example-case-09', '{"id":"example-case-09","isExample":true,"title":"[예시] 보험 해약환급금이 있는 경우의 상담 흐름","category":"보험","author":"가상 사례","originalDebt":0,"remainingDebt":0,"lawyerId":"","lawyerName":"예시","lawyerAvatar":"","content":"① 가입한 보험과 해약환급금을 조회합니다. ② 변호사가 재산목록에 보험을 어떻게 적는지 설명합니다. ③ 일부 보험의 해약환급금이 압류금지 재산으로 다뤄지는 기준을 안내받습니다. ④ 해약 여부는 변호사와 상의한 뒤 정합니다. 실제 진행 여부와 결과는 개별 사정과 법원 판단에 따라 달라집니다.","tags":["#상담절차","#예시"]}'::jsonb, 'draft', true, 108),
  ('example-case-10', '{"id":"example-case-10","isExample":true,"title":"[예시] 자동차 할부가 남아 있는 경우","category":"자동차 담보","author":"가상 사례","originalDebt":0,"remainingDebt":0,"lawyerId":"","lawyerName":"예시","lawyerAvatar":"","content":"① 차량 할부 잔액과 시세를 정리합니다. ② 변호사가 담보가 있는 채무(별제권)의 처리 방식을 설명합니다. ③ 업무에 차가 꼭 필요한지 함께 검토합니다. ④ 자동차등록원부 등 자료를 안내받습니다. 실제 진행 여부와 결과는 개별 사정과 법원 판단에 따라 달라집니다.","tags":["#상담절차","#예시"]}'::jsonb, 'draft', true, 109),
  ('example-case-11', '{"id":"example-case-11","isExample":true,"title":"[예시] 집 담보대출이 있는 경우의 상담 흐름","category":"주택 담보","author":"가상 사례","originalDebt":0,"remainingDebt":0,"lawyerId":"","lawyerName":"예시","lawyerAvatar":"","content":"① 주택 시세와 담보대출 잔액을 정리합니다. ② 변호사가 집을 유지하면서 진행할 수 있는 방법이 있는지 검토합니다. ③ 청산가치 계산에 집이 어떻게 반영되는지 설명을 듣습니다. ④ 등기사항전부증명서 등 서류를 안내받습니다. 실제 진행 여부와 결과는 개별 사정과 법원 판단에 따라 달라집니다.","tags":["#상담절차","#예시"]}'::jsonb, 'draft', true, 110),
  ('example-case-12', '{"id":"example-case-12","isExample":true,"title":"[예시] 세금 체납이 함께 있는 경우","category":"세금 체납","author":"가상 사례","originalDebt":0,"remainingDebt":0,"lawyerId":"","lawyerName":"예시","lawyerAvatar":"","content":"① 국세·지방세·건강보험료 체납액을 나눠 적습니다. ② 변호사가 세금은 우선채권이라 처리 방식이 다르다는 점을 설명합니다. ③ 체납 내역 확인 서류를 안내받습니다. ④ 분납 등 다른 방법도 함께 상담합니다. 실제 진행 여부와 결과는 개별 사정과 법원 판단에 따라 달라집니다.","tags":["#상담절차","#예시"]}'::jsonb, 'draft', true, 111),
  ('example-case-13', '{"id":"example-case-13","isExample":true,"title":"[예시] 부모님 채무를 상속받게 된 경우","category":"상속 채무","author":"가상 사례","originalDebt":0,"remainingDebt":0,"lawyerId":"","lawyerName":"예시","lawyerAvatar":"","content":"① 상속 개시 시점과 알게 된 시점을 정리합니다. ② 변호사가 한정승인·상속포기 기한과 차이를 설명합니다. ③ 상속재산과 채무 목록을 안내받습니다. ④ 기한이 지난 경우 가능한 방법을 상담합니다. 실제 진행 여부와 결과는 개별 사정과 법원 판단에 따라 달라집니다.","tags":["#상담절차","#예시"]}'::jsonb, 'draft', true, 112),
  ('example-case-14', '{"id":"example-case-14","isExample":true,"title":"[예시] 개인회생 진행 중 소득이 줄어든 경우","category":"회생 중 변화","author":"가상 사례","originalDebt":0,"remainingDebt":0,"lawyerId":"","lawyerName":"예시","lawyerAvatar":"","content":"① 줄어든 소득과 시점을 정리합니다. ② 변호사가 변제계획 변경 신청을 검토할 수 있는지 설명합니다. ③ 소득 감소를 보여 줄 자료를 안내받습니다. ④ 변제금이 밀리기 전에 상담하는 것이 좋다는 안내를 받습니다. 실제 진행 여부와 결과는 개별 사정과 법원 판단에 따라 달라집니다.","tags":["#상담절차","#예시"]}'::jsonb, 'draft', true, 113),
  ('example-case-15', '{"id":"example-case-15","isExample":true,"title":"[예시] 예전에 신용회복을 하다 중단한 경우","category":"과거 이력","author":"가상 사례","originalDebt":0,"remainingDebt":0,"lawyerId":"","lawyerName":"예시","lawyerAvatar":"","content":"① 이전 채무조정의 진행 기간과 중단 사유를 정리합니다. ② 변호사가 지금 신청할 수 있는 절차를 설명합니다. ③ 이전 조정 내역 확인 방법을 안내받습니다. ④ 남은 채무를 다시 정리합니다. 실제 진행 여부와 결과는 개별 사정과 법원 판단에 따라 달라집니다.","tags":["#상담절차","#예시"]}'::jsonb, 'draft', true, 114),
  ('example-case-16', '{"id":"example-case-16","isExample":true,"title":"[예시] 예전에 면책을 받은 적이 있는 경우","category":"과거 이력","author":"가상 사례","originalDebt":0,"remainingDebt":0,"lawyerId":"","lawyerName":"예시","lawyerAvatar":"","content":"① 이전 면책 결정 시기를 확인합니다. ② 변호사가 다시 신청할 때의 기간 제한을 설명합니다. ③ 결정문 등 이전 사건 자료를 안내받습니다. ④ 지금 상황에 맞는 절차를 상담합니다. 실제 진행 여부와 결과는 개별 사정과 법원 판단에 따라 달라집니다.","tags":["#상담절차","#예시"]}'::jsonb, 'draft', true, 115),
  ('example-case-17', '{"id":"example-case-17","isExample":true,"title":"[예시] 일용직·현장 근로자의 소득 입증","category":"일용직","author":"가상 사례","originalDebt":0,"remainingDebt":0,"lawyerId":"","lawyerName":"예시","lawyerAvatar":"","content":"① 일한 날짜와 받은 금액을 정리합니다. ② 변호사가 소득이 일정하지 않을 때 쓰는 자료를 설명합니다. ③ 통장 입금 내역·근로 확인서 등을 안내받습니다. ④ 평균 소득을 어떻게 잡는지 상담합니다. 실제 진행 여부와 결과는 개별 사정과 법원 판단에 따라 달라집니다.","tags":["#상담절차","#예시"]}'::jsonb, 'draft', true, 116),
  ('example-case-18', '{"id":"example-case-18","isExample":true,"title":"[예시] 배달·플랫폼 소득자의 상담 흐름","category":"프리랜서 회생","author":"가상 사례","originalDebt":0,"remainingDebt":0,"lawyerId":"","lawyerName":"예시","lawyerAvatar":"","content":"① 플랫폼별 정산 내역을 모읍니다. ② 변호사가 사업소득·필요경비 처리 방식을 설명합니다. ③ 종합소득세 신고 자료를 안내받습니다. ④ 소득 변동이 클 때의 준비 방법을 상담합니다. 실제 진행 여부와 결과는 개별 사정과 법원 판단에 따라 달라집니다.","tags":["#상담절차","#예시"]}'::jsonb, 'draft', true, 117),
  ('example-case-19', '{"id":"example-case-19","isExample":true,"title":"[예시] 가족에게 알리지 않고 진행하고 싶은 경우","category":"비밀 상담","author":"가상 사례","originalDebt":0,"remainingDebt":0,"lawyerId":"","lawyerName":"예시","lawyerAvatar":"","content":"① 스텔스 가명으로 상담을 요청합니다. ② 변호사가 법원 우편·서류에서 가족이 알 수 있는 부분을 설명합니다. ③ 배우자 재산 자료가 필요한 경우를 안내받습니다. ④ 연락 방법과 시간대를 정합니다. 실제 진행 여부와 결과는 개별 사정과 법원 판단에 따라 달라집니다.","tags":["#상담절차","#예시"]}'::jsonb, 'draft', true, 118),
  ('example-case-20', '{"id":"example-case-20","isExample":true,"title":"[예시] 지급명령을 받은 경우의 상담 흐름","category":"소송·지급명령","author":"가상 사례","originalDebt":0,"remainingDebt":0,"lawyerId":"","lawyerName":"예시","lawyerAvatar":"","content":"① 받은 날짜와 사건번호를 확인합니다. ② 변호사가 이의신청 기한과 다른 절차와의 관계를 설명합니다. ③ 받은 서류를 사진으로 올려 함께 봅니다. ④ 필요한 대응 순서를 정합니다. 실제 진행 여부와 결과는 개별 사정과 법원 판단에 따라 달라집니다.","tags":["#상담절차","#예시"]}'::jsonb, 'draft', true, 119),
  ('example-case-21', '{"id":"example-case-21","isExample":true,"title":"[예시] 통장이 압류되어 생활비가 막힌 경우","category":"계좌 압류","author":"가상 사례","originalDebt":0,"remainingDebt":0,"lawyerId":"","lawyerName":"예시","lawyerAvatar":"","content":"① 압류된 계좌와 금액을 정리합니다. ② 변호사가 압류금지 금액과 생계비계좌 제도를 설명합니다. ③ 압류 범위 변경 신청 등 방법을 안내받습니다. ④ 회생·파산 신청과 함께 할 일을 상담합니다. 실제 진행 여부와 결과는 개별 사정과 법원 판단에 따라 달라집니다.","tags":["#상담절차","#예시"]}'::jsonb, 'draft', true, 120),
  ('example-case-22', '{"id":"example-case-22","isExample":true,"title":"[예시] 소득이 생계비보다 적은 경우의 파산 검토","category":"개인파산","author":"가상 사례","originalDebt":0,"remainingDebt":0,"lawyerId":"","lawyerName":"예시","lawyerAvatar":"","content":"① 가족 수와 월 소득·지출을 정리합니다. ② 변호사가 파산과 회생의 요건 차이를 설명합니다. ③ 최근 재산 처분·지급불능 시점을 함께 확인합니다. ④ 파산 준비 서류 목록을 안내받습니다. 실제 진행 여부와 결과는 개별 사정과 법원 판단에 따라 달라집니다.","tags":["#상담절차","#예시"]}'::jsonb, 'draft', true, 121),
  ('example-case-23', '{"id":"example-case-23","isExample":true,"title":"[예시] 보증을 선 가족 사업이 어려워진 경우","category":"연대보증 채무","author":"가상 사례","originalDebt":0,"remainingDebt":0,"lawyerId":"","lawyerName":"예시","lawyerAvatar":"","content":"① 보증 계약서와 주채무자의 상황을 정리합니다. ② 변호사가 보증채무가 본인 채무로 다뤄지는 방식을 설명합니다. ③ 주채무자의 절차 진행 여부를 함께 확인합니다. ④ 구상채무 처리 방식을 안내받습니다. 실제 진행 여부와 결과는 개별 사정과 법원 판단에 따라 달라집니다.","tags":["#상담절차","#예시"]}'::jsonb, 'draft', true, 122),
  ('example-case-24', '{"id":"example-case-24","isExample":true,"title":"[예시] 투자 손실이 1년 안에 생긴 경우","category":"코인/주식 손실","author":"가상 사례","originalDebt":0,"remainingDebt":0,"lawyerId":"","lawyerName":"예시","lawyerAvatar":"","content":"① 투자 시기와 손실 금액을 정리합니다. ② 변호사가 투자 손실이 변제금 판단에 미칠 수 있는 영향을 법원 실무 기준으로 설명합니다. ③ 거래 내역 등 소명 자료를 안내받습니다. ④ 관할 법원별 실무 차이를 상담합니다. 실제 진행 여부와 결과는 개별 사정과 법원 판단에 따라 달라집니다.","tags":["#상담절차","#예시"]}'::jsonb, 'draft', true, 123),
  ('example-case-25', '{"id":"example-case-25","isExample":true,"title":"[예시] 도박 채무가 있는 경우의 상담 흐름","category":"도박 채무","author":"가상 사례","originalDebt":0,"remainingDebt":0,"lawyerId":"","lawyerName":"예시","lawyerAvatar":"","content":"① 채무가 생긴 시기와 현재 상황을 사실대로 적습니다. ② 변호사가 파산 면책불허가 사유와 회생 절차를 나눠 설명합니다. ③ 치료·상담 기록 등 준비할 자료를 안내받습니다. ④ 재량면책 등 법원 판단 기준을 상담합니다. 실제 진행 여부와 결과는 개별 사정과 법원 판단에 따라 달라집니다.","tags":["#상담절차","#예시"]}'::jsonb, 'draft', true, 124),
  ('example-case-26', '{"id":"example-case-26","isExample":true,"title":"[예시] 외국에서 일하다 돌아온 경우","category":"소득 공백","author":"가상 사례","originalDebt":0,"remainingDebt":0,"lawyerId":"","lawyerName":"예시","lawyerAvatar":"","content":"① 해외 근무 기간과 귀국 뒤 소득을 정리합니다. ② 변호사가 국내 소득 자료가 짧을 때 준비 방법을 설명합니다. ③ 출입국 사실증명 등 서류를 안내받습니다. ④ 앞으로의 소득 계획을 상담합니다. 실제 진행 여부와 결과는 개별 사정과 법원 판단에 따라 달라집니다.","tags":["#상담절차","#예시"]}'::jsonb, 'draft', true, 125),
  ('example-case-27', '{"id":"example-case-27","isExample":true,"title":"[예시] 월세를 내며 혼자 사는 경우","category":"1인 가구","author":"가상 사례","originalDebt":0,"remainingDebt":0,"lawyerId":"","lawyerName":"예시","lawyerAvatar":"","content":"① 월세·보증금과 계약 명의를 정리합니다. ② 변호사가 1인 가구 생계비와 주거비 기준을 설명합니다. ③ 임대차계약서 사본을 안내받습니다. ④ 소득에 맞는 절차를 상담합니다. 실제 진행 여부와 결과는 개별 사정과 법원 판단에 따라 달라집니다.","tags":["#상담절차","#예시"]}'::jsonb, 'draft', true, 126),
  ('example-case-28', '{"id":"example-case-28","isExample":true,"title":"[예시] 자녀 셋을 키우는 가정의 상담 흐름","category":"다자녀 가정","author":"가상 사례","originalDebt":0,"remainingDebt":0,"lawyerId":"","lawyerName":"예시","lawyerAvatar":"","content":"① 가족 구성과 교육비 지출을 정리합니다. ② 변호사가 부양가족 수가 생계비 판단에 쓰이는 방식을 설명합니다. ③ 가족관계증명서 등 서류를 안내받습니다. ④ 변제기간 단축 사유가 있는지 함께 확인합니다. 실제 진행 여부와 결과는 개별 사정과 법원 판단에 따라 달라집니다.","tags":["#상담절차","#예시"]}'::jsonb, 'draft', true, 127),
  ('example-case-29', '{"id":"example-case-29","isExample":true,"title":"[예시] 장애가 있는 가족을 돌보는 경우","category":"부양가족","author":"가상 사례","originalDebt":0,"remainingDebt":0,"lawyerId":"","lawyerName":"예시","lawyerAvatar":"","content":"① 돌보는 가족과 의료·간병비를 정리합니다. ② 변호사가 추가 생계비를 주장할 수 있는지 법원 기준을 설명합니다. ③ 장애인 증명서·진료비 자료를 안내받습니다. ④ 필요한 소명 방식을 상담합니다. 실제 진행 여부와 결과는 개별 사정과 법원 판단에 따라 달라집니다.","tags":["#상담절차","#예시"]}'::jsonb, 'draft', true, 128),
  ('example-case-30', '{"id":"example-case-30","isExample":true,"title":"[예시] 면책 뒤 다시 생활을 정리하는 경우","category":"면책 후","author":"가상 사례","originalDebt":0,"remainingDebt":0,"lawyerId":"","lawyerName":"예시","lawyerAvatar":"","content":"① 면책 결정 이후 남은 채무가 있는지 확인합니다. ② 변호사가 면책되지 않는 채권(세금 등)을 설명합니다. ③ 압류 해제 등 남은 절차를 안내받습니다. ④ 신용 회복 과정을 상담합니다. 실제 진행 여부와 결과는 개별 사정과 법원 판단에 따라 달라집니다.","tags":["#상담절차","#예시"]}'::jsonb, 'draft', true, 129)
